// Synthetic Exchange-style timezone, with no real calendar/user data.
export function outlookCalendar(month = '09', extra = '') {
  return `BEGIN:VCALENDAR
VERSION:2.0
BEGIN:VTIMEZONE
TZID:Central European Standard Time
BEGIN:STANDARD
DTSTART:19701025T030000
TZOFFSETFROM:+0200
TZOFFSETTO:+0100
RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU
END:STANDARD
BEGIN:DAYLIGHT
DTSTART:19700329T020000
TZOFFSETFROM:+0100
TZOFFSETTO:+0200
RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU
END:DAYLIGHT
END:VTIMEZONE
BEGIN:VEVENT
UID:synthetic-exchange-event
DTSTART;VALUE=DATE-TIME;TZID="Central European Standard Time":2026${month}10T090000
DTEND;TZID="Central European Standard Time":2026${month}10T100000
SUMMARY:Planning
${extra}END:VEVENT
END:VCALENDAR
`.replaceAll('\n', '\r\n');
}
